1	package payflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"math"
10		"os"
11		"path/filepath"
12		"sort"
13		"sync"
14	)
15	
16	// 账本磁盘格式（单文件，一个 JSON 文档，末附 sha256 校验和）：
17	//
18	//	{"version":1,
19	//	 "initial_balances":[{"account":"aa","asset":"usdc","balance":1000}],
20	//	 "balances":[{"account":"aa","asset":"usdc","balance":700}],
21	//	 "settlements":[{...一笔成功结算及其当时费率...}],
22	//	 "refunds":[{...一笔成功全额退款...}],
23	//	 "checksum":"<sha256 of the document without checksum>"}
24	//
25	// initial_balances 在初始化时冻结，用于检测任何对历史余额/记录的篡改；
26	// checksum 覆盖截断、比特翻转与所有语义编辑。
27	//
28	// refunds 字段缺省（旧版账本没有该字段）即视为空列表：旧文件可直接打开；
29	// 只要账本没有发生退款，写回时该字段继续缺省，读取旧账本不会改写文件。
30	//
31	// 写入采用“临时文件 + fsync + 原子 rename + 目录 fsync”，
32	// 因此崩溃后磁盘上只会存在完整的旧版本或完整新版本，
33	// 不会出现“扣款/退款无记录”或“记录未改余额”的中间状态。
34	const ledgerVersion = 1
35	
36	// 结算结果状态，与命令行输出一一对应，可分别识别。
37	const (
38		StatusSettled         = "settled"              // 成功扣款
39		StatusDuplicate       = "duplicate"            // 幂等重试：字段与原记录一致，返回原结算/原退款，不再入账
40		StatusConflict        = "conflict"             // 编号冲突：编号已成功但字段或费率/目标或原因不同
41		StatusState           = "state_error"          // 非 pending
42		StatusFunds           = "insufficient_balance" // 余额不足（含不存在的账户/资产组合）
43		StatusLimitExceeded   = "limit_exceeded"       // 本次批次该 (账户, 资产) 组合的扣款上限不足
44		StatusInvalid         = "invalid_parameter"
45		StatusStorage         = "storage_error"
46		StatusRefundSuccess   = "refunded"         // 成功全额退回
47		StatusNotFound        = "not_found"        // 退款目标结算不存在（含原付款只曾失败）
48		StatusAlreadyRefunded = "already_refunded" // 原付款已被其他退款编号全额退回
49	)
50	
51	// 拒绝原因。
52	const (
53		reasonEmptyID         = "intent id must not be empty"
54		reasonEmptyAccount    = "account must not be empty"
55		reasonEmptyAsset      = "asset must not be empty"
56		reasonBadAmount       = "amount must be a positive int64"
57		reasonOverflow        = "amount plus fee overflows int64"
58		reasonNotPending      = "intent is not pending"
59		reasonFunds           = "insufficient balance for amount plus fee"
60		reasonLimitExceeded   = "charge limit exceeded for %s/%s: max_charged %d, used %d, this item charges %d"
61		reasonDuplicate       = "duplicate settlement attempt"
62		reasonConflict        = "settlement id conflicts with a different request"
63		reasonEmptyRefundID   = "refund id must not be empty"
64		reasonEmptySettlement = "settlement_id must not be empty"
65		reasonEmptyReason     = "refund reason must not be empty"
66		reasonSettlementGone  = "settlement %q not found"
67		reasonAlreadyRefunded = "settlement %q has already been refunded by %q"
68		reasonRefundConflict  = "refund id conflicts with a different request"
69		reasonDuplicateRefund = "duplicate refund attempt"
70	)
71	
72	// BalanceInit 是初始化时一个 (账户, 资产) 组合的起始余额。
73	type BalanceInit struct {
74		Account string `json:"account"`
75		Asset   string `json:"asset"`
76		Balance int64  `json:"balance"`
77	}
78	
79	// PaymentIntent 是批次中的一项付款请求。金额使用指针以区分“缺省/null”与 0。
80	type PaymentIntent struct {
81		ID        string `json:"id"`
82		Account   string `json:"account"`
83		Paymaster string `json:"paymaster"`
84		Asset     string `json:"asset"`
85		Amount    *int64 `json:"amount"`
86		Nonce     uint64 `json:"nonce"`
87		State     string `json:"state"`
88	}
89	
90	// ChargeLimit 是本次提交中一个 (账户, 资产) 组合的扣款上限：该组合在本批次内
91	// 成功落账的 charged（付款金额 + 手续费）累计不得超过 max_charged。
92	// 上限仅对本次提交有效，不持久化；历史扣款与退款都不占本次额度。
93	// MaxCharged 使用指针以区分“缺省/null”与显式给出的 0（0 表示禁止该组合新增扣款）。
94	type ChargeLimit struct {
95		Account    string `json:"account"`
96		Asset      string `json:"asset"`
97		MaxCharged *int64 `json:"max_charged"`
98	}
99	
100	// FeeBatch 是一次提交：固定费率（基点）+ 有序意图列表 + 可选的本次扣款上限。
101	// Limits 缺省、为 null 或为空数组时不限制扣款。
102	type FeeBatch struct {
103		FeeBps  int             `json:"fee_bps"`
104		Intents []PaymentIntent `json:"intents"`
105		Limits  []ChargeLimit   `json:"limits,omitempty"`
106	}
107	
108	// Record 是一笔成功结算留下的永久记录，按成功先后顺序保存。
109	type Record struct {
110		ID        string `json:"id"`
111		Account   string `json:"account"`
112		Paymaster string `json:"paymaster"`
113		Asset     string `json:"asset"`
114		Amount    int64  `json:"amount"`
115		Nonce     uint64 `json:"nonce"`
116		FeeBps    int    `json:"fee_bps"`
117		Fee       int64  `json:"fee"`
118		Charged   int64  `json:"charged"`
119		Seq       int64  `json:"seq"`
120	}
121	
122	// ItemResult 是批次中一项的处理结果，顺序与输入逐项对应。
123	type ItemResult struct {
124		ID     string  `json:"id"`
125		Status string  `json:"status"`
126		Reason string  `json:"reason,omitempty"`
127		Record *Record `json:"record,omitempty"`
128	}
129	
130	// BatchResult 是一次提交的结果。空批次对应空 Results。
131	type BatchResult struct {
132		Results []ItemResult `json:"results"`
133	}
134	
135	// PreviewResult 是一次提交预览（--dry-run）的结果。DryRun 恒为 true，
136	// 用于与真实提交输出区分；Results 与输入逐项对应，状态、失败原因与结算
137	// 记录格式与 Submit 完全一致——其中 settled 表示“按当前账本预计能够成功”，
138	// 携带的记录使用从当前最大付款序号之后连续递增的预计序号。
139	// 预览不写入账本，序号、余额与本批次额度都不会被预留。
140	type PreviewResult struct {
141		DryRun  bool         `json:"dry_run"`
142		Results []ItemResult `json:"results"`
143	}
144	
145	// RefundRequest 是退款批次中的一项：退款编号、原付款编号、退款原因，三者均须非空。
146	type RefundRequest struct {
147		ID           string `json:"id"`
148		SettlementID string `json:"settlement_id"`
149		Reason       string `json:"reason"`
150	}
151	
152	// RefundBatch 是一次退款提交：有序的退款请求列表。
153	type RefundBatch struct {
154		Refunds []RefundRequest `json:"refunds"`
155	}
156	
157	// RefundRecord 是一笔成功全额退款留下的永久记录，按退款成功先后顺序保存。
158	// 退款金额与去向（账户/资产/总额）全部由原结算记录确定，因此一并冗余记录，
159	// 使每条退款都能脱离上下文自解释、可追溯原结算。
160	// AfterSeq 是退款落账时结算历史的长度：余额校验要求该结算在此时点之前发生。
161	type RefundRecord struct {
162		ID           string `json:"id"`
163		SettlementID string `json:"settlement_id"`
164		Reason       string `json:"reason"`
165		Account      string `json:"account"`
166		Asset        string `json:"asset"`
167		Amount       int64  `json:"amount"`
168		Fee          int64  `json:"fee"`
169		Charged      int64  `json:"charged"`
170		AfterSeq     int64  `json:"after_seq"`
171		Seq          int64  `json:"seq"`
172	}
173	
174	// RefundResult 是一项退款的处理结果。成功与幂等重复携带原付款编号、账户、
175	// 资产、退款总额与原因；失败只带状态与说明。
176	type RefundResult struct {
177		ID           string        `json:"id"`
178		Status       string        `json:"status"`
179		Reason       string        `json:"reason,omitempty"`
180		SettlementID string        `json:"settlement_id,omitempty"`
181		Account      string        `json:"account,omitempty"`
182		Asset        string        `json:"asset,omitempty"`
183		Charged      int64         `json:"charged,omitempty"`
184		Record       *RefundRecord `json:"record,omitempty"`
185	}
186	
187	// RefundBatchResult 是一次退款提交的结果，顺序与输入逐项对应。
188	type RefundBatchResult struct {
189		Results []RefundResult `json:"results"`
190	}
191	
192	// BalanceView 是一个 (账户, 资产) 组合的当前余额。
193	type BalanceView struct {
194		Account string `json:"account"`
195		Asset   string `json:"asset"`
196		Balance int64  `json:"balance"`
197	}
198	
199	// Snapshot 是账本查询结果。Refunds 按退款成功先后排列，无退款时为空列表。
200	type Snapshot struct {
201		Balances    []BalanceView  `json:"balances"`
202		Settlements []Record       `json:"settlements"`
203		Refunds     []RefundRecord `json:"refunds"`
204	}
205	
206	// LedgerError 携带可机读分类（与 ItemResult.Status 对齐）和说明。
207	type LedgerError struct {
208		Kind    string
209		Message string
210	}
211	
212	func (e *LedgerError) Error() string { return e.Kind + ": " + e.Message }
213	
214	// 错误分类。
215	const (
216		ErrInvalid = "invalid_parameter"
217		ErrExists  = "ledger_exists"
218		ErrCorrupt = "corrupt_ledger"
219		ErrStorage = "storage_error"
220		ErrClosed  = "ledger_closed"
221		ErrNotInit = "ledger_not_initialized"
222	)
223	
224	func ledgerError(kind, format string, args ...any) error {
225		return &LedgerError{Kind: kind, Message: fmt.Sprintf(format, args...)}
226	}
227	
228	// KindOf 返回错误的分类；非账本错误按存储错误处理。
229	func KindOf(err error) string {
230		var le *LedgerError
231		if errors.As(err, &le) {
232			return le.Kind
233		}
234		return ErrStorage
235	}
236	
237	// FailWriter 注入存储故障：返回 true 时本次持久化失败，
238	// 内存状态必须回滚到该项执行之前。仅用于测试。
239	type FailWriter interface {
240		FailNextPersist() bool
241	}
242	
243	type balanceKey struct {
244		account string
245		asset   string
246	}
247	
248	type ledgerState struct {
249		Version     int
250		Initial     map[balanceKey]int64 // 初始化时冻结的起始余额，仅用于完整性校验
251		Balances    map[balanceKey]int64 // 当前余额
252		Settlements []Record
253		Refunds     []RefundRecord
254	}
255	
256	// 磁盘文档字段（顺序即签名时的规范顺序，不得调整，否则旧文件校验失败）。
257	// Refunds 使用 omitempty：旧版账本缺省该字段即可读入为 nil（视为空），
258	// 且无退款的账本写回时继续省略该字段。
259	type unsignedDoc struct {
260		Version     int            `json:"version"`
261		Initial     []BalanceView  `json:"initial_balances"`
262		Balances    []BalanceView  `json:"balances"`
263		Settlements []Record       `json:"settlements"`
264		Refunds     []RefundRecord `json:"refunds,omitempty"`
265	}
266	
267	type signedDoc struct {
268		unsignedDoc
269		Checksum string `json:"checksum"`
270	}
271	
272	func balanceList(m map[balanceKey]int64) []BalanceView {
273		out := make([]BalanceView, 0, len(m))
274		for k, v := range m {
275			out = append(out, BalanceView{Account: k.account, Asset: k.asset, Balance: v})
276		}
277		sortBalances(out)
278		return out
279	}
280	
281	func balanceMap(list []BalanceView) (map[balanceKey]int64, error) {
282		out := make(map[balanceKey]int64, len(list))
283		for i, b := range list {
284			if b.Account == "" || b.Asset == "" {
285				return nil, ledgerError(ErrCorrupt, "balance %d has empty account or asset", i)
286			}
287			if b.Balance < 0 {
288				return nil, ledgerError(ErrCorrupt, "negative balance for %s/%s", b.Account, b.Asset)
289			}
290			k := balanceKey{b.Account, b.Asset}
291			if _, dup := out[k]; dup {
292				return nil, ledgerError(ErrCorrupt, "duplicate balance entry for %s/%s", b.Account, b.Asset)
293			}
294			out[k] = b.Balance
295		}
296		return out, nil
297	}
298	
299	// MarshalJSON 输出带 sha256 校验和的单个 JSON 文档。
300	func (s *ledgerState) MarshalJSON() ([]byte, error) {
301		settlements := s.Settlements
302		if settlements == nil {
303			settlements = []Record{}
304		}
305		doc := unsignedDoc{
306			Version:     s.Version,
307			Initial:     balanceList(s.Initial),
308			Balances:    balanceList(s.Balances),
309			Settlements: settlements,
310			Refunds:     s.Refunds, // nil 时因 omitempty 省略，保持无退款账本的旧格式
311		}
312		payload, err := json.Marshal(doc)
313		if err != nil {
314			return nil, err
315		}
316		sum := checksumHex(payload)
317		out := make([]byte, 0, len(payload)+len(sum)+16)
318		out = append(out, payload[:len(payload)-1]...) // 去掉结尾 '}'
319		out = append(out, []byte(`,"checksum":"`+sum+`"}`)...)
320		return out, nil
321	}
322	
323	// UnmarshalJSON 校验 checksum、结构不变式并重放全部记录。
324	func (s *ledgerState) UnmarshalJSON(data []byte) error {
325		var doc signedDoc
326		if err := json.Unmarshal(data, &doc); err != nil {
327			return err
328		}
329		if doc.Checksum == "" {
330			return ledgerError(ErrCorrupt, "missing checksum")
331		}
332		payload, err := json.Marshal(doc.unsignedDoc)
333		if err != nil {
334			return ledgerError(ErrCorrupt, "re-encode ledger: %v", err)
335		}
336		if got := checksumHex(payload); got != doc.Checksum {
337			return ledgerError(ErrCorrupt, "checksum mismatch: file %s, want %s", doc.Checksum, got)
338		}
339		if doc.Version != ledgerVersion {
340			return ledgerError(ErrCorrupt, "unsupported ledger version %d", doc.Version)
341		}
342		initial, err := balanceMap(doc.Initial)
343		if err != nil {
344			return err
345		}
346		current, err := balanceMap(doc.Balances)
347		if err != nil {
348			return err
349		}
350		records := doc.Settlements
351		if records == nil {
352			records = []Record{}
353		}
354		refunds := doc.Refunds // 旧版账本缺省该字段，nil 视为空列表
355		if refunds == nil {
356			refunds = []RefundRecord{}
357		}
358		if err := validateAndReplay(initial, current, records, refunds); err != nil {
359			return err
360		}
361		s.Version = doc.Version
362		s.Initial = initial
363		s.Balances = current
364		s.Settlements = records
365		s.Refunds = refunds
366		return nil
367	}
368	
369	func decodeState(data []byte) (*ledgerState, error) {
370		var state ledgerState
371		if err := json.Unmarshal(data, &state); err != nil {
372			if le, ok := err.(*LedgerError); ok && le.Kind == ErrCorrupt {
373				return nil, err
374			}
375			return nil, ledgerError(ErrCorrupt, "parse ledger: %v", err)
376		}
377		return &state, nil
378	}
379	
380	// canonicalLedgerPath 把绝对路径解析为账本的规范路径：解析目录与文件本身
381	// 的符号链接，使同一账本经不同路径（如指向账本所在目录的软链接）打开时
382	// 共享同一注册表项、同一份内存状态与互斥锁。账本文件尚不存在时（未初始化）
383	// 解析其父目录；父目录也无法解析时退回原路径。
384	func canonicalLedgerPath(abs string) string {
385		if resolved, err := filepath.EvalSymlinks(abs); err == nil {
386			return resolved
387		}
388		if resolved, err := filepath.EvalSymlinks(filepath.Dir(abs)); err == nil {
389			return filepath.Join(resolved, filepath.Base(abs))
390		}
391		return abs
392	}
393	
394	// CreateLedger 在 path 处创建新账本。所有初始数据先校验，
395	// 任一不合法则返回 ErrInvalid 且不创建任何文件；
396	// 路径上已有账本则返回 ErrExists，绝不覆盖历史。
397	func CreateLedger(path string, init []BalanceInit) error {
398		if err := validateInitial(init); err != nil {
399			return err
400		}
401		abs, err := filepath.Abs(path)
402		if err != nil {
403			return ledgerError(ErrStorage, "resolve path: %v", err)
404		}
405		abs = canonicalLedgerPath(abs)
406	
407		openMu.Lock()
408		defer openMu.Unlock()
409	
410		if _, err := os.Stat(abs); err == nil {
411			return ledgerError(ErrExists, "ledger already exists at %s", abs)
412		} else if !errors.Is(err, os.ErrNotExist) {
413			return ledgerError(ErrStorage, "stat %s: %v", abs, err)
414		}
415		if openRegistry[abs] != nil {
416			return ledgerError(ErrExists, "ledger is already initialized in this process")
417		}
418	
419		state := &ledgerState{
420			Version:     ledgerVersion,
421			Initial:     make(map[balanceKey]int64, len(init)),
422			Balances:    make(map[balanceKey]int64, len(init)),
423			Settlements: []Record{},
424			Refunds:     []RefundRecord{},
425		}
426		for _, b := range init {
427			k := balanceKey{b.Account, b.Asset}
428			state.Initial[k] = b.Balance
429			state.Balances[k] = b.Balance
430		}
431		if err := atomicWrite(abs, state); err != nil {
432			return err
433		}
434		openRegistry[abs] = &registryEntry{state: state}
435		return nil
436	}
437	
438	func validateInitial(init []BalanceInit) error {
439		seen := map[balanceKey]bool{}
440		for i, b := range init {
441			if b.Account == "" {
442				return ledgerError(ErrInvalid, "initial balance %d: account must not be empty", i)
443			}
444			if b.Asset == "" {
445				return ledgerError(ErrInvalid, "initial balance %d: asset must not be empty", i)
446			}
447			if b.Balance < 0 {
448				return ledgerError(ErrInvalid, "initial balance %d (%s/%s): balance must be non-negative", i, b.Account, b.Asset)
449			}
450			k := balanceKey{b.Account, b.Asset}
451			if seen[k] {
452				return ledgerError(ErrInvalid, "initial balance %d: duplicate entry for %s/%s", i, b.Account, b.Asset)
453			}
454			seen[k] = true
455		}
456		return nil
457	}
458	
459	// Ledger 是一个可持久化的本地账本。同一进程内指向同一账本文件的多次 Open
460	// （包括经目录软链接的不同路径）返回共享同一状态与互斥锁的实例，
461	// 因此并发提交按同一本账本串行化。
462	type Ledger struct {
463		path string
464		reg  *registryEntry
465		open bool
466	}
467	
468	type registryEntry struct {
469		mu       sync.Mutex // 保护 state；整个批次串行持有
470		state    *ledgerState
471		refs     int        // 打开的句柄数
472		ops      int        // 正在执行的 Submit/Query 数
473		failHook FailWriter // 仅测试注入
474	}
475	
476	// tryEvict 仅在没有句柄且没有在途操作时注销注册表项。
477	// 调用方必须持有 openMu。
478	func tryEvict(path string, reg *registryEntry) {
479		if reg.refs == 0 && reg.ops == 0 && openRegistry[path] == reg {
480			delete(openRegistry, path)
481		}
482	}
483	
484	var (
485		openMu       sync.Mutex
486		openRegistry = map[string]*registryEntry{}
487	)
488	
489	// Open 打开（或复用）path 处的账本。账本必须已由 CreateLedger 初始化；
490	// 文件缺失返回 ErrNotInit，内容损坏返回 ErrCorrupt，不会被当成空账本重来。
491	func Open(path string) (*Ledger, error) {
492		abs, err := filepath.Abs(path)
493		if err != nil {
494			return nil, ledgerError(ErrStorage, "resolve path: %v", err)
495		}
496		abs = canonicalLedgerPath(abs)
497	
498		openMu.Lock()
499		defer openMu.Unlock()
500	
501		if reg := openRegistry[abs]; reg != nil {
502			reg.refs++
503			return &Ledger{path: abs, reg: reg, open: true}, nil
504		}
505	
506		data, err := os.ReadFile(abs)
507		if err != nil {
508			if errors.Is(err, os.ErrNotExist) {
509				return nil, ledgerError(ErrNotInit, "no ledger at %s; initialize it first", abs)
510			}
511			return nil, ledgerError(ErrStorage, "read %s: %v", abs, err)
512		}
513		if len(bytes.TrimSpace(data)) == 0 {
514			return nil, ledgerError(ErrCorrupt, "ledger file %s is empty", abs)
515		}
516		dec := json.NewDecoder(bytes.NewReader(data))
517		var rawDoc json.RawMessage
518		if err := dec.Decode(&rawDoc); err != nil {
519			return nil, ledgerError(ErrCorrupt, "parse %s: %v", abs, err)
520		}
521		// 不允许尾随内容：防止文件被拼接/截断后被误读为合法。
522		if tok, err := dec.Token(); err != io.EOF {
523			if err == nil {
524				return nil, ledgerError(ErrCorrupt, "unexpected trailing data after ledger document (token %v)", tok)
525			}
526			return nil, ledgerError(ErrCorrupt, "trailing data after ledger document: %v", err)
527		}
528		state, err := decodeState(rawDoc)
529		if err != nil {
530			return nil, err
531		}
532	
533		reg := &registryEntry{state: state, refs: 1}
534		openRegistry[abs] = reg
535		return &Ledger{path: abs, reg: reg, open: true}, nil
536	}
537	
538	// Close 释放句柄；同一进程可再次 Open 同一文件并继续使用。
539	// 若关闭时有在途提交，注册表项保留到在途操作结束，避免并发 Open
540	// 从磁盘重新加载而丢失正在写入的状态。
541	func (l *Ledger) Close() error {
542		openMu.Lock()
543		defer openMu.Unlock()
544		if !l.open {
545			return nil
546		}
547		l.open = false
548		l.reg.refs--
549		tryEvict(l.path, l.reg)
550		return nil
551	}
552	
553	// beginOp 标记一次在途操作。返回 nil 表示句柄已关闭。
554	func (l *Ledger) beginOp() error {
555		openMu.Lock()
556		defer openMu.Unlock()
557		if !l.open {
558			return ledgerError(ErrClosed, "ledger handle is closed")
559		}
560		l.reg.ops++
561		return nil
562	}
563	
564	func (l *Ledger) endOp() {
565		openMu.Lock()
566		defer openMu.Unlock()
567		l.reg.ops--
568		tryEvict(l.path, l.reg)
569	}
570	
571	// feeFor 计算手续费：amount*feeBps/10000 向下取整。
572	// amount>0、0<=feeBps<=10000 时朴素乘积可能溢出 int64，
573	// 拆成商和余数两部分即可在 int64 内精确完成。
574	func feeFor(amount int64, feeBps int) int64 {
575		hi := amount / 10000
576		lo := amount % 10000
577		return hi*int64(feeBps) + (lo*int64(feeBps))/10000
578	}
579	
580	func validateIntent(it PaymentIntent) (int64, string, bool) {
581		if it.ID == "" {
582			return 0, reasonEmptyID, false
583		}
584		if it.Account == "" {
585			return 0, reasonEmptyAccount, false
586		}
587		if it.Asset == "" {
588			return 0, reasonEmptyAsset, false
589		}
590		if it.Amount == nil || *it.Amount <= 0 {
591			return 0, reasonBadAmount, false
592		}
593		return *it.Amount, "", true
594	}
595	
596	// validateLimits 校验本次提交的扣款上限：账户与资产必须非空，同一组合不得重复，
597	// max_charged 必须明确提供且为非负 int64。任一不合法则整个批次拒绝（ErrInvalid），
598	// 与意图列表是否为空无关。合法时返回按组合索引的上限表；无上限时返回 nil。
599	func validateLimits(limits []ChargeLimit) (map[balanceKey]int64, error) {
600		if len(limits) == 0 {
601			return nil, nil
602		}
603		out := make(map[balanceKey]int64, len(limits))
604		for i, l := range limits {
605			if l.Account == "" {
606				return nil, ledgerError(ErrInvalid, "limit %d: account must not be empty", i)
607			}
608			if l.Asset == "" {
609				return nil, ledgerError(ErrInvalid, "limit %d: asset must not be empty", i)
610			}
611			if l.MaxCharged == nil {
612				return nil, ledgerError(ErrInvalid, "limit %d (%s/%s): max_charged must be provided", i, l.Account, l.Asset)
613			}
614			if *l.MaxCharged < 0 {
615				return nil, ledgerError(ErrInvalid, "limit %d (%s/%s): max_charged must be non-negative, got %d", i, l.Account, l.Asset, *l.MaxCharged)
616			}
617			k := balanceKey{l.Account, l.Asset}
618			if _, dup := out[k]; dup {
619				return nil, ledgerError(ErrInvalid, "limit %d: duplicate entry for %s/%s", i, l.Account, l.Asset)
620			}
621			out[k] = *l.MaxCharged
622		}
623		return out, nil
624	}
625	
626	// Submit 按输入顺序结算一个批次。各项独立成功或失败：后项看到前项
627	// 成功后的余额；任一项失败不影响其余项（存储错误只回滚出错项本身，
628	// 已完成的前项不回滚）。结果与输入逐项对应，空批次返回空结果。
629	//
630	// 若批次携带 limits，则每个列出的 (账户, 资产) 组合在本次提交内的成功扣款
631	// 累计（含手续费）不得超过其 max_charged：超限的项返回 limit_exceeded，
632	// 不扣余额、不留记录、不占编号与额度；未列出的组合不限制。额度按本次提交
633	// 从零计算，只有成功落账的扣款消耗额度，历史扣款与退款均不计入。
634	func (l *Ledger) Submit(batch FeeBatch) (*BatchResult, error) {
635		if err := l.beginOp(); err != nil {
636			return nil, err
637		}
638		defer l.endOp()
639		limits, err := validateBatch(batch)
640		if err != nil {
641			return nil, err
642		}
643	
644		l.reg.mu.Lock()
645		defer l.reg.mu.Unlock()
646	
647		results := runBatch(batch, limits, l.reg.state, l.persistCharge)
648		return &BatchResult{Results: results}, nil
649	}
650	
651	// Preview 在不写入账本的前提下，按当前账本预计算一个批次的结算结果，
652	// 语义与 Submit 逐项一致（状态、失败原因、结算记录格式均相同）：
653	//   - 后项看到前项“预计成功”后的可用余额与本批次已用限额；
654	//   - 预计成功的新付款使用从当前最大付款序号之后连续递增的序号，
655	//     失败、重复、冲突不消耗序号；
656	//   - 已有成功编号仍按原付款字段与费率判断重复或冲突（原付款已退款也一样），
657	//     重复项携带原记录，不占余额与本批次额度；本批次首次预计成功的编号对
658	//     后续项同样生效（相同请求重复、字段不同冲突），失败项不占编号；
659	//   - 手续费、金额溢出、状态与限额判断沿用实际提交规则，同时超限与余额不足
660	//     仍先报告超限，限额只累计本次预计成功的扣款（含手续费）。
661	//
662	// 预览全程在当前状态的深拷贝上进行：不持久化、不修改真实余额与历史，
663	// 任何编号、序号和额度都不被预留；连续预览相同批次（账本未变化）结果一致，
664	// 随后真实提交仍按首次提交处理。预览只预测业务结果，不承诺真实提交时的
665	// 写入成功（因此预览结果中不会出现 storage_error）。费率或限额非法属于
666	// 批次级错误，返回 invalid_parameter 且不产生部分结果（空批次同样检查）。
667	func (l *Ledger) Preview(batch FeeBatch) (*PreviewResult, error) {
668		if err := l.beginOp(); err != nil {
669			return nil, err
670		}
671		defer l.endOp()
672		limits, err := validateBatch(batch)
673		if err != nil {
674			return nil, err
675		}
676	
677		l.reg.mu.Lock()
678		defer l.reg.mu.Unlock()
679	
680		// 在快照副本上模拟：预览结束后真实状态与磁盘文件保持原样。
681		sim := cloneState(l.reg.state)
682		results := runBatch(batch, limits, sim, simulateCharge)
683		return &PreviewResult{DryRun: true, Results: results}, nil
684	}
685	
686	// validateBatch 执行批次级校验：费率范围与本次扣款上限。任一不合法都返回
687	// 批次级错误（invalid_parameter），调用方不得执行任何意图（空批次同样检查）。
688	func validateBatch(batch FeeBatch) (map[balanceKey]int64, error) {
689		if batch.FeeBps < 0 || batch.FeeBps > 10000 {
690			return nil, ledgerError(ErrInvalid, "fee_bps must be within [0,10000], got %d", batch.FeeBps)
691		}
692		// 限额非法是批次级错误：任何意图都不执行（空意图列表同样检查）。
693		return validateLimits(batch.Limits)
694	}
695	
696	// chargeEffect 是一笔预计成功扣款的全部账本效果：扣哪个组合、扣多少、
697	// 留下什么结算记录。它由付款规则产生，本身尚未生效；是否生效、如何生效
698	// （真实落盘或预览模拟）由生效策略决定。
699	type chargeEffect struct {
700		key    balanceKey
701		total  int64
702		record Record
703	}
704	
705	// commitCharge 是扣款生效策略：把一笔预计成功的扣款应用到状态 st 上。
706	// 返回 nil 表示已生效；返回非 nil 表示保存失败，且 st 必须已恢复到
707	// 该项执行之前的余额与历史。
708	type commitCharge func(st *ledgerState, eff chargeEffect) error
709	
710	// runBatch 按输入顺序在给定状态 st 上处理整个批次，返回逐项结果。
711	// 付款规则（judgeIntent）与扣款生效（commit）分离：规则只读取 st 与
712	// 本批次已用额度给出判定和预计扣款效果，不改动任何状态；生效策略决定
713	// 效果如何落地——真实提交先改内存再原子落盘、失败回滚并报告
714	// storage_error，预览只在副本上推进内存状态、绝不落盘。两种操作共用
715	// 同一份规则，因此逐项判定完全一致。调用方必须持有 reg.mu。
716	func runBatch(batch FeeBatch, limits map[balanceKey]int64, st *ledgerState, commit commitCharge) []ItemResult {
717		out := make([]ItemResult, 0, len(batch.Intents))
718	
719		// 本次批次内各组合已消耗的额度，从零开始，仅成功生效的扣款计入。
720		used := make(map[balanceKey]int64, len(limits))
721	
722		for i := range batch.Intents {
723			it := &batch.Intents[i]
724	
725			// 1. 规则判定：纯读取，不产生任何副作用。
726			res, charge := judgeIntent(it, batch.FeeBps, limits, used, st)
727			if charge == nil {
728				out = append(out, res)
729				continue
730			}
731	
732			// 2. 生效：保存失败时 commit 已回滚该项（余额与历史恢复原样），
733			//    该项报告 storage_error，不留记录、不占额度，后项继续处理。
734			if err := commit(st, *charge); err != nil {
735				res.Status = StatusStorage
736				res.Reason = err.Error()
737				out = append(out, res)
738				continue
739			}
740	
741			// 3. 只有成功生效的扣款才消耗本批次额度（预览同样如此）。
742			used[charge.key] += charge.total
743			cp := charge.record
744			res.Status = StatusSettled
745			res.Record = &cp
746			out = append(out, res)
747		}
748		return out
749	}
750	
751	// judgeIntent 按付款规则评估一项请求，只读取状态与额度用量，不产生副作用。
752	// 返回逐项结果；预计成功时结果只填编号，扣款效果以 chargeEffect 描述，
753	// 由调用方交给生效策略落地。判定顺序即对外约定：参数校验、已成功编号的
754	// 重复/冲突、状态、溢出、本批次限额（先于余额）、余额。
755	func judgeIntent(it *PaymentIntent, feeBps int, limits map[balanceKey]int64, used map[balanceKey]int64, st *ledgerState) (ItemResult, *chargeEffect) {
756		res := ItemResult{ID: it.ID}
757	
758		// 1. 参数校验。未通过的编号不占用去重资格。
759		amount, reason, ok := validateIntent(*it)
760		if !ok {
761			res.Status = StatusInvalid
762			res.Reason = reason
763			return res, nil
764		}
765	
766		// 2. 已成功编号：字段与费率完全一致则幂等返回原记录；
767		//    任一不同则编号冲突。两者都不再扣款、不改原记录。
768		//    本批次内先（预计）成功的同编号项也在此被看到。
769		if rec, exists := findRecordIn(st.Settlements, it.ID); exists {
770			if sameRequest(rec, it, amount, feeBps) {
771				cp := rec
772				res.Status = StatusDuplicate
773				res.Reason = reasonDuplicate
774				res.Record = &cp
775			} else {
776				res.Status = StatusConflict
777				res.Reason = reasonConflict
778			}
779			return res, nil
780		}
781	
782		// 3. 状态错误单独报告（不占用去重资格，之后可重新提交）。
783		if it.State != "" && it.State != "pending" {
784			res.Status = StatusState
785			res.Reason = reasonNotPending
786			return res, nil
787		}
788	
789		// 4. 手续费与扣款总额（溢出明确按参数错误拒绝）。
790		fee := feeFor(amount, feeBps)
791		if fee > math.MaxInt64-amount {
792			res.Status = StatusInvalid
793			res.Reason = reasonOverflow
794			return res, nil
795		}
796		total := amount + fee
797	
798		key := balanceKey{it.Account, it.Asset}
799	
800		// 5. 本次批次限额（先于余额判断：同时超限与余额不足时报告超限）。
801		//    恰好达到上限仍允许；用 total > max-used 而非 used+total > max，
802		//    避免累计接近 int64 上界时溢出放行。失败不消耗额度。
803		if max, capped := limits[key]; capped {
804			if u := used[key]; total > max-u {
805				res.Status = StatusLimitExceeded
806				res.Reason = fmt.Sprintf(reasonLimitExceeded, it.Account, it.Asset, max, u, total)
807				return res, nil
808			}
809		}
810	
811		// 6. 余额校验。不存在的账户/资产组合余额视为 0（不足）。
812		if total > st.Balances[key] {
813			res.Status = StatusFunds
814			res.Reason = reasonFunds
815			return res, nil
816		}
817	
818		// 7. 预计成功：描述扣款效果（序号按当前历史长度连续递增）。
819		return res, &chargeEffect{
820			key:   key,
821			total: total,
822			record: Record{
823				ID:        it.ID,
824				Account:   it.Account,
825				Paymaster: it.Paymaster,
826				Asset:     it.Asset,
827				Amount:    amount,
828				Nonce:     it.Nonce,
829				FeeBps:    feeBps,
830				Fee:       fee,
831				Charged:   total,
832				Seq:       int64(len(st.Settlements)) + 1,
833			},
834		}
835	}
836	
837	// simulateCharge 是预览的生效策略：只在（副本）状态上推进余额与历史，
838	// 绝不触碰磁盘，因此不会失败，预览结果中也不会出现 storage_error。
839	func simulateCharge(st *ledgerState, eff chargeEffect) error {
840		st.Balances[eff.key] -= eff.total
841		st.Settlements = append(st.Settlements, eff.record)
842		return nil
843	}
844	
845	// persistCharge 是真实提交的生效策略：先在内存生效，再原子落盘；
846	// 落盘失败回滚该项（恢复余额与历史），并返回存储错误。
847	func (l *Ledger) persistCharge(st *ledgerState, eff chargeEffect) error {
848		rollback := stageOn(st, eff.key, st.Balances[eff.key]-eff.total, eff.record)
849		if err := l.persistLocked(); err != nil {
850			rollback()
851			return err
852		}
853		return nil
854	}
855	
856	// cloneState 返回账本状态的独立深拷贝，供预览在副本上模拟而不触碰真实状态。
857	func cloneState(st *ledgerState) *ledgerState {
858		cp := &ledgerState{
859			Version:     st.Version,
860			Initial:     make(map[balanceKey]int64, len(st.Initial)),
861			Balances:    make(map[balanceKey]int64, len(st.Balances)),
862			Settlements: append([]Record(nil), st.Settlements...),
863			Refunds:     append([]RefundRecord(nil), st.Refunds...),
864		}
865		for k, v := range st.Initial {
866			cp.Initial[k] = v
867		}
868		for k, v := range st.Balances {
869			cp.Balances[k] = v
870		}
871		return cp
872	}
873	
874	// findRecordIn 在给定结算历史中按编号查找成功记录。
875	func findRecordIn(records []Record, id string) (Record, bool) {
876		// 记录按成功顺序追加且 ID 唯一；单机账本量级直接扫描。
877		for _, r := range records {
878			if r.ID == id {
879				return r, true
880			}
881		}
882		return Record{}, false
883	}
884	
885	// stageOn 在指定状态上应用一笔扣款与记录，返回回滚函数（恢复该项执行前的
886	// 余额与记录长度）。
887	func stageOn(st *ledgerState, key balanceKey, newBal int64, rec Record) func() {
888		oldBal, hadKey := st.Balances[key]
889		oldLen := len(st.Settlements)
890		st.Balances[key] = newBal
891		st.Settlements = append(st.Settlements, rec)
892		return func() {
893			if hadKey {
894				st.Balances[key] = oldBal
895			} else {
896				delete(st.Balances, key)
897			}
898			st.Settlements = st.Settlements[:oldLen]
899		}
900	}
901	
902	// Refund 按输入顺序处理一个退款批次。各项独立处理：后项能看到前项成功退回的
903	// 余额；任一项失败不影响其余项（存储错误只回滚出错项本身，前项保留，后项继续）。
904	// 结果与输入逐项对应，空批次返回空结果。
905	//
906	// 语义：
907	//   - 参数合法时，已成功的退款编号优先判定：目标结算与原因都相同返回 duplicate
908	//     及原退款记录（不再入账）；任一不同返回 conflict。
909	//   - 新退款编号：找不到成功结算（含原付款只曾失败）返回 not_found；
910	//     该结算已被其他退款编号退回返回 refunded，不增加余额。
911	//   - 成功时把原记录的 charged（含当时已扣手续费）全额退回原账户、原资产；
912	//     退款金额与去向完全由原结算确定，原结算记录及其编号、顺序保持不变。
913	//   - 失败申请不占用退款编号，之后可修改原因或目标再提交。
914	func (l *Ledger) Refund(batch RefundBatch) (*RefundBatchResult, error) {
915		if err := l.beginOp(); err != nil {
916			return nil, err
917		}
918		defer l.endOp()
919		out := &RefundBatchResult{Results: make([]RefundResult, 0, len(batch.Refunds))}
920	
921		l.reg.mu.Lock()
922		defer l.reg.mu.Unlock()
923	
924		for i := range batch.Refunds {
925			req := &batch.Refunds[i]
926			res := RefundResult{ID: req.ID}
927	
928			// 1. 参数校验：退款编号、原付款编号、原因三者都必须非空。
929			//    未通过的编号不占用退款资格。
930			if req.ID == "" {
931				res.Status = StatusInvalid
932				res.Reason = reasonEmptyRefundID
933				out.Results = append(out.Results, res)
934				continue
935			}
936			if req.SettlementID == "" {
937				res.Status = StatusInvalid
938				res.Reason = reasonEmptySettlement
939				out.Results = append(out.Results, res)
940				continue
941			}
942			if req.Reason == "" {
943				res.Status = StatusInvalid
944				res.Reason = reasonEmptyReason
945				out.Results = append(out.Results, res)
946				continue
947			}
948	
949			// 2. 已成功退款编号优先判定：目标与原因都相同则幂等返回原退款记录；
950			//    任一不同则冲突。两者都不再入账。本批次内先成功的同编号项也在此可见。
951			if prior, exists := l.findRefund(req.ID); exists {
952				if prior.SettlementID == req.SettlementID && prior.Reason == req.Reason {
953					cp := prior
954					res.Status = StatusDuplicate
955					res.Reason = prior.Reason
956					res.SettlementID = prior.SettlementID
957					res.Account = prior.Account
958					res.Asset = prior.Asset
959					res.Charged = prior.Charged
960					res.Record = &cp
961				} else {
962					res.Status = StatusConflict
963					res.Reason = reasonRefundConflict
964				}
965				out.Results = append(out.Results, res)
966				continue
967			}
968	
969			// 3. 新退款编号：目标必须是一笔成功结算（原付款只曾失败也算不存在）。
970			target, exists := l.findRecord(req.SettlementID)
971			if !exists {
972				res.Status = StatusNotFound
973				res.Reason = fmt.Sprintf(reasonSettlementGone, req.SettlementID)
974				out.Results = append(out.Results, res)
975				continue
976			}
977	
978			// 4. 每笔原付款最多退回一次：已被其他退款编号退回则报告已退款，不加余额。
979			if prior, refunded := l.findRefundOfSettlement(req.SettlementID); refunded {
980				res.Status = StatusAlreadyRefunded
981				res.Reason = fmt.Sprintf(reasonAlreadyRefunded, req.SettlementID, prior.ID)
982				out.Results = append(out.Results, res)
983				continue
984			}
985	
986			// 5. 全额退回原账户、原资产（amount 与当时手续费一并退回），
987			//    与退款记录在同一个原子写入中落盘；保存失败回滚该项。
988			rec := RefundRecord{
989				ID:           req.ID,
990				SettlementID: target.ID,
991				Reason:       req.Reason,
992				Account:      target.Account,
993				Asset:        target.Asset,
994				Amount:       target.Amount,
995				Fee:          target.Fee,
996				Charged:      target.Charged,
997				AfterSeq:     int64(len(l.reg.state.Settlements)),
998				Seq:          int64(len(l.reg.state.Refunds)) + 1,
999			}
1000			key := balanceKey{target.Account, target.Asset}
1001			bal := l.reg.state.Balances[key]
1002			rollback := l.stageRefund(key, bal+target.Charged, rec)
1003			if err := l.persistLocked(); err != nil {
1004				rollback()
1005				res.Status = StatusStorage
1006				res.Reason = err.Error()
1007			} else {
1008				cp := rec
1009				res.Status = StatusRefundSuccess
1010				res.Reason = rec.Reason
1011				res.SettlementID = rec.SettlementID
1012				res.Account = rec.Account
1013				res.Asset = rec.Asset
1014				res.Charged = rec.Charged
1015				res.Record = &cp
1016			}
1017			out.Results = append(out.Results, res)
1018		}
1019		return out, nil
1020	}
1021	
1022	// stageRefund 应用一笔退款（余额增加 + 记录追加），返回回滚函数。
1023	func (l *Ledger) stageRefund(key balanceKey, newBal int64, rec RefundRecord) func() {
1024		oldBal, hadKey := l.reg.state.Balances[key]
1025		oldLen := len(l.reg.state.Refunds)
1026		l.reg.state.Balances[key] = newBal
1027		l.reg.state.Refunds = append(l.reg.state.Refunds, rec)
1028		return func() {
1029			if hadKey {
1030				l.reg.state.Balances[key] = oldBal
1031			} else {
1032				delete(l.reg.state.Balances, key)
1033			}
1034			l.reg.state.Refunds = l.reg.state.Refunds[:oldLen]
1035		}
1036	}
1037	
1038	func (l *Ledger) findRefund(id string) (RefundRecord, bool) {
1039		// 退款按成功顺序追加且 ID 唯一；单机账本量级直接扫描。
1040		for _, r := range l.stateView().Refunds {
1041			if r.ID == id {
1042				return r, true
1043			}
1044		}
1045		return RefundRecord{}, false
1046	}
1047	
1048	// findRefundOfSettlement 返回退回指定结算的那笔退款（每笔结算最多一笔）。
1049	func (l *Ledger) findRefundOfSettlement(settlementID string) (RefundRecord, bool) {
1050		for _, r := range l.stateView().Refunds {
1051			if r.SettlementID == settlementID {
1052				return r, true
1053			}
1054		}
1055		return RefundRecord{}, false
1056	}
1057	
1058	func (l *Ledger) stateView() *ledgerState { return l.reg.state }
1059	
1060	func (l *Ledger) findRecord(id string) (Record, bool) {
1061		// 记录按成功顺序追加且 ID 唯一；条目规模在单机账本量级，直接扫描。
1062		for _, r := range l.stateView().Settlements {
1063			if r.ID == id {
1064				return r, true
1065			}
1066		}
1067		return Record{}, false
1068	}
1069	
1070	// sameRequest 比较全部付款字段与费率。付款字段：账户、付款方、资产、金额、nonce。
1071	func sameRequest(r Record, it *PaymentIntent, amount int64, feeBps int) bool {
1072		return r.Account == it.Account &&
1073			r.Paymaster == it.Paymaster &&
1074			r.Asset == it.Asset &&
1075			r.Amount == amount &&
1076			r.Nonce == it.Nonce &&
1077			r.FeeBps == feeBps
1078	}
1079	
1080	// Query 返回余额视图（按账户、资产排序，保证确定性）与按成功先后排列的记录。
1081	func (l *Ledger) Query() (*Snapshot, error) {
1082		if err := l.beginOp(); err != nil {
1083			return nil, err
1084		}
1085		defer l.endOp()
1086		l.reg.mu.Lock()
1087		defer l.reg.mu.Unlock()
1088	
1089		st := l.stateView()
1090		bals := make([]BalanceView, 0, len(st.Balances))
1091		for k, v := range st.Balances {
1092			bals = append(bals, BalanceView{Account: k.account, Asset: k.asset, Balance: v})
1093		}
1094		sortBalances(bals)
1095		recs := make([]Record, len(st.Settlements))
1096		copy(recs, st.Settlements)
1097		refunds := make([]RefundRecord, len(st.Refunds))
1098		copy(refunds, st.Refunds)
1099		return &Snapshot{Balances: bals, Settlements: recs, Refunds: refunds}, nil
1100	}
1101	
1102	// Balance 返回单个 (账户, 资产) 组合的余额；组合不存在按 0 处理。
1103	func (l *Ledger) Balance(account, asset string) (int64, error) {
1104		if err := l.beginOp(); err != nil {
1105			return 0, err
1106		}
1107		defer l.endOp()
1108		l.reg.mu.Lock()
1109		defer l.reg.mu.Unlock()
1110		return l.stateView().Balances[balanceKey{account, asset}], nil
1111	}
1112	
1113	func sortBalances(bals []BalanceView) {
1114		sort.Slice(bals, func(i, j int) bool {
1115			if bals[i].Account != bals[j].Account {
1116				return bals[i].Account < bals[j].Account
1117			}
1118			return bals[i].Asset < bals[j].Asset
1119		})
1120	}
1121	
1122	// persistLocked 将当前状态原子写入磁盘；调用方必须持有 reg.mu。
1123	func (l *Ledger) persistLocked() error {
1124		if l.reg.failHook != nil && l.reg.failHook.FailNextPersist() {
1125			return ledgerError(ErrStorage, "injected write failure")
1126		}
1127		return atomicWrite(l.path, l.stateView())
1128	}
1129	
1130	// SetFailHook 为该路径的账本安装存储故障注入，仅用于测试。
1131	func SetFailHook(l *Ledger, fw FailWriter) {
1132		l.reg.failHook = fw
1133	}
1134

