56	// assertClosedHandle 断言已关闭句柄上的每一类操作都返回 ledger_closed：
57	// 错误必须明确（余额返回 0 但同时带错，不能被当成合法的空查询；
58	// Query 不得返回空快照代替错误），且不产生任何业务结果。
59	func assertClosedHandle(t *testing.T, l *Ledger) {
60		t.Helper()
61	
62		if _, err := l.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
63			intent("late", "aa", "usdc", 1),
64		}}); KindOf(err) != ErrClosed {
65			t.Fatalf("Submit on closed handle: want %s, got %v", ErrClosed, err)
66		}
67		if bal, err := l.Balance("aa", "usdc"); KindOf(err) != ErrClosed || bal != 0 {
68			t.Fatalf("Balance on closed handle: want %s with zero value, got bal=%d err=%v", ErrClosed, bal, err)
69		}
70		if snap, err := l.Query(); KindOf(err) != ErrClosed || snap != nil {
71			t.Fatalf("Query on closed handle: want %s with nil snapshot, got snap=%+v err=%v", ErrClosed, snap, err)
72		}
73		if _, err := l.Preview(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
74			intent("late", "aa", "usdc", 1),
75		}}); KindOf(err) != ErrClosed {
76			t.Fatalf("Preview on closed handle: want %s, got %v", ErrClosed, err)
77		}
78		if _, err := l.Refund(RefundBatch{Refunds: []RefundRequest{
79			refundReq("r-late", "p1", "x"),
80		}}); KindOf(err) != ErrClosed {
81			t.Fatalf("Refund on closed handle: want %s, got %v", ErrClosed, err)
82		}
83	}
