379	// 核心回归（保存失败分支）：唯一打开的句柄在一笔付款已经开始、保存
380	// 尚未完成时关闭并随即重开，而该笔付款最终保存失败。它仍必须按逐项
381	// 结果返回 storage_error（批次本身不报错），新句柄看到余额恢复为 100、
382	// 历史中没有这笔付款；失败编号不占去重资格，用原编号付 60 首次成功、
383	// 余额变为 40。关闭与重开不能保留失败付款的扣款或去重资格。
384	func TestReopenDuringFailingPaymentRollsBackForNewHandle(t *testing.T) {
385		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 100}})
386		l1, err := Open(path)
387		if err != nil {
388			t.Fatal(err)
389		}
390		t.Cleanup(func() { l1.Close() })
391	
392		hook := newGatedPersistHook(true) // 窗口放行后本次保存失败
393		SetFailHook(l1, hook)
394		t.Cleanup(func() { SetFailHook(l1, nil) })
395	
396		type outcome struct {
397			res *BatchResult
398			err error
399		}
400		done := make(chan outcome, 1)
401		go func() {
402			res, err := l1.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
403				intent("p1", "aa", "usdc", 70),
404			}})
405			done <- outcome{res, err}
406		}()
407		<-hook.entered
408	
409		if err := l1.Close(); err != nil {
410			t.Fatalf("close during in-flight payment: %v", err)
411		}
412		l2, err := Open(path)
413		if err != nil {
414			t.Fatalf("reopen while payment in flight: %v", err)
415		}
416		t.Cleanup(func() { l2.Close() })
417	
418		close(hook.release)
419		got := <-done
420		// storage_error 是逐项业务结果（与成功、参数/状态/余额等业务失败、
421		// ledger_closed 账本错误都不同），而不是批次级错误。
422		if got.err != nil {
423			t.Fatalf("storage failure must be reported as an item result, got batch err=%v", got.err)
424		}
425		if got.res == nil || got.res.Results[0].Status != StatusStorage {
426			t.Fatalf("in-flight payment want storage_error item result, got %+v err=%v", got.res, got.err)
427		}
428	
429		// 旧句柄已关闭；新句柄看到回滚后的完整状态。
430		assertClosedHandle(t, l1)
431		if bal, _ := l2.Balance("aa", "usdc"); bal != 100 {
432			t.Fatalf("new handle balance after failed save=%d want 100", bal)
433		}
434		snap, _ := l2.Query()
435		if len(snap.Settlements) != 0 {
436			t.Fatalf("failed payment must leave no success record: %+v", snap.Settlements)
437		}
438		if len(snap.Refunds) != 0 {
439			t.Fatalf("failed payment must leave no refunds: %+v", snap.Refunds)
440		}
441		// 磁盘同样保持旧状态：余额 100、无记录。
442		if bal, n := persistedBalanceAndCount(t, path, "aa", "usdc"); bal != 100 || n != 0 {
443			t.Fatalf("persisted state after failed save: bal=%d records=%d, want 100/0", bal, n)
444		}
445	
446		// 原失败编号仍可用于合法付款：付 60 首次成功（不是 duplicate），
447		// 序号从 1 开始，余额变为 40。
448		retry, err := l2.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
449			intent("p1", "aa", "usdc", 60),
450		}})
451		if err != nil {
452			t.Fatal(err)
453		}
454		rr := retry.Results[0]
455		if rr.Status != StatusSettled || rr.Record == nil {
456			t.Fatalf("reuse of failed id want first-time settled, got %+v", rr)
457		}
458		if rr.Record.Seq != 1 || rr.Record.Amount != 60 || rr.Record.Charged != 60 {
459			t.Fatalf("retry settlement record: %+v", rr.Record)
460		}
461		if bal, _ := l2.Balance("aa", "usdc"); bal != 40 {
462			t.Fatalf("balance after retry=%d want 40", bal)
463		}
464		// 持久化恰发生两次：失败的 70 一次、成功的 60 一次；关闭从不写盘。
465		if n := hook.calls.Load(); n != 2 {
466			t.Fatalf("persist calls=%d want 2", n)
467		}
468	
