259	func TestIdempotencyAndConflict(t *testing.T) {
260		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 1_000_000}})
261		l := openOrFail(t, path)
262		base := intent("p1", "aa", "usdc", 1500)
263		base.Paymaster = "pm-1"
264		base.Nonce = 7
265	
266		first, _ := l.Submit(FeeBatch{FeeBps: 30, Intents: []PaymentIntent{base}})
267		if first.Results[0].Status != StatusSettled {
268			t.Fatalf("first: %+v", first.Results[0])
269		}
270		balAfterFirst, _ := l.Balance("aa", "usdc")
271	
272		// 完全相同（含费率）→ 幂等，返回原记录，不再扣款。
273		again, _ := l.Submit(FeeBatch{FeeBps: 30, Intents: []PaymentIntent{base}})
274		a := again.Results[0]
275		if a.Status != StatusDuplicate || a.Record == nil || a.Record.Seq != 1 {
276			t.Fatalf("identical retry want duplicate with original record, got %+v", a)
277		}
278		if bal, _ := l.Balance("aa", "usdc"); bal != balAfterFirst {
279			t.Fatalf("duplicate charged again: %d vs %d", bal, balAfterFirst)
280		}
281	
282		// 任一付款字段或费率不同 → 冲突，原记录保持不变。
283		mutations := []func(*PaymentIntent, *int){
284			func(it *PaymentIntent, bps *int) { it.Account = "other" },
285			func(it *PaymentIntent, bps *int) { it.Paymaster = "pm-2" },
286			func(it *PaymentIntent, bps *int) { it.Asset = "eth" },
287			func(it *PaymentIntent, bps *int) { *it.Amount = 1501 },
288			func(it *PaymentIntent, bps *int) { it.Nonce = 8 },
289			func(it *PaymentIntent, bps *int) { *bps = 31 },
290		}
291		for i, mut := range mutations {
292			it := base
293			bps := 30
294			mut(&it, &bps)
295			res, _ := l.Submit(FeeBatch{FeeBps: bps, Intents: []PaymentIntent{it}})
296			if res.Results[0].Status != StatusConflict {
297				t.Fatalf("mutation %d want conflict, got %+v", i, res.Results[0])
298			}
299		}
300		snap, _ := l.Query()
301		if len(snap.Settlements) != 1 || snap.Settlements[0].Amount != 1500 || snap.Settlements[0].FeeBps != 30 {
302			t.Fatalf("original record changed after conflicts: %+v", snap.Settlements)
303		}
304		if bal, _ := l.Balance("aa", "usdc"); bal != balAfterFirst {
305			t.Fatalf("conflict changed balance: %d vs %d", bal, balAfterFirst)
306		}
307	}
