1000		for i, req := range []RefundRequest{
1001			refundReq("r1", "p1", "reason B"),
1002			refundReq("r1", "p2", "reason A"),
1003		} {
1004			res, _ := l.Refund(RefundBatch{Refunds: []RefundRequest{req}})
1005			if res.Results[0].Status != StatusConflict {
