1531		legacy := func(balance int64, records ...Record) []byte {
1532			type doc struct {
1533				Version     int           `json:"version"`
1534				Initial     []BalanceView `json:"initial_balances"`
1535				Balances    []BalanceView `json:"balances"`
1536				Settlements []Record      `json:"settlements"`
1537			}
