// tryEvict 仅在没有句柄且没有在途操作时注销注册表项。
// 调用方必须持有 openMu。
func tryEvict(path string, reg *registryEntry) {
	if reg.refs == 0 && reg.ops == 0 && openRegistry[path] == reg {
		delete(openRegistry, path)
	}
}

