	// 报损坏，而不是沿用上一次成功读到的 900 余额。
	tampered := bytes.Clone(restored)
	tampered[10] ^= 0x01
	writeFileAt(t, path, tampered)
	assertOpenFails(t, path, ErrCorrupt)
