// 初始化后尚无任何句柄：文件被清空、只留白字符或被截断成半个 JSON，
// 首次 Open 必须报 corrupt_ledger，且原字节不得被修补或覆盖。
func TestFirstOpenOnEmptyOrTruncatedFileIsCorrupt(t *testing.T) {
	good := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 500}})
	raw, err := os.ReadFile(good)
	if err != nil {
		t.Fatal(err)
	}

	cases := map[string][]byte{
		"empty":         nil,
		"whitespace":    []byte("   \n\t  "),
		"truncated json": raw[:len(raw)/2],
		"open brace":    []byte("{"),
	}
	for name, content := range cases {
		t.Run(name, func(t *testing.T) {
			path := filepath.Join(t.TempDir(), "ledger.json")
			writeFileAt(t, path, content)
			before, _ := os.ReadFile(path)

			assertOpenFails(t, path, ErrCorrupt)

			after, statErr := os.ReadFile(path)
			if statErr != nil {
				t.Fatalf("failed open must not remove the file: %v", statErr)
			}
			if !bytes.Equal(before, after) {
				t.Fatalf("failed open must not repair/rewrite the file")
			}
		})
	}
}

// 初始化后尚无任何句柄：把文件改成校验和不匹配的内容（比特翻转或
// 语义编辑），首次 Open 必须报 corrupt_ledger，且文件逐字节不变。
func TestFirstOpenOnChecksumMismatchIsCorrupt(t *testing.T) {
	good := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 500}})
	raw, err := os.ReadFile(good)
	if err != nil {
		t.Fatal(err)
	}

	tamper := func(mut func([]byte) []byte) []byte {
		return mut(bytes.Clone(raw))
	}
	cases := map[string][]byte{
		"bitflip": tamper(func(b []byte) []byte {
			b[10] ^= 0x01
			return b
		}),
		"semantic edit": tamper(func(b []byte) []byte {
			return bytes.ReplaceAll(b, []byte(`"balance":500`), []byte(`"balance":999`))
		}),
	}
	for name, content := range cases {
		t.Run(name, func(t *testing.T) {
			path := filepath.Join(t.TempDir(), "ledger.json")
			writeFileAt(t, path, content)

			assertOpenFails(t, path, ErrCorrupt)

			after, err := os.ReadFile(path)
			if err != nil {
				t.Fatal(err)
			}
			if !bytes.Equal(after, content) {
				t.Fatalf("failed open must leave the corrupt file byte-intact")
			}
		})
	}
}

